node -e "
const fs=require('fs');
const data=JSON.parse(fs.readFileSync('e:/Desktop/Projects/ecomGliders/content/config/case-studies.json','utf8'));
const studies=data.caseStudies;
console.log('COUNT', studies.length);
console.log('FILTERS', JSON.stringify(data.filters));
console.log('INDEX', JSON.stringify(data.index,null,2).slice(0,500));
const keys=new Set();
studies.forEach(s=>Object.keys(s).forEach(k=>keys.add(k)));
console.log('TOP_KEYS', [...keys].sort());
studies.forEach((s,i)=>{
  const issues=[];
  if(!s.featuredImage) issues.push('no featuredImage');
  if(!s.heroSubheadline) issues.push('no heroSubheadline');
  if(!s.challenge?.paragraphs?.length) issues.push('empty challenge');
  if(!s.solution?.steps?.length) issues.push('empty solution');
  if(!s.results?.metrics?.length) issues.push('empty results');
  if(!s.quote) issues.push('no quote');
  if(!s.seo) issues.push('no seo');
  // detect placeholder/generic content
  const stepTitles=(s.solution?.steps||[]).map(x=>x.title).join('|');
  if(stepTitles.includes('Audit and diagnosis') && stepTitles.includes('Targeted execution') && stepTitles.includes('Measurement and iteration')) {
    issues.push('generic solution steps');
  }
  const challengeText=(s.challenge?.paragraphs||[]).join(' ');
  if(/placeholder|TODO|TBD|lorem|coming soon|content pending/i.test(challengeText+JSON.stringify(s))) issues.push('placeholder text');
  // short excerpts
  if((s.excerpt||'').length<40) issues.push('short excerpt');
  if((s.challenge?.paragraphs||[]).every(p=>p.length<80)) issues.push('thin challenge paras');
  console.log('---', s.slug);
  console.log('  client:', s.client);
  console.log('  service:', s.service, '| filter:', s.serviceFilter, '| cat:', s.category);
  console.log('  metric:', s.metric, s.metricLabel);
  console.log('  image:', s.featuredImage||'(empty)');
  console.log('  challenge paras:', s.challenge?.paragraphs?.length, 'solution steps:', s.solution?.steps?.length, 'metrics:', s.results?.metrics?.length);
  console.log('  quote:', s.quote? 'yes':'NO');
  console.log('  seo title:', s.seo?.title||'(none)');
  console.log('  ISSUES:', issues.length? issues.join('; ') : 'none');
  // print first 80 chars of challenge
  console.log('  challenge[0]:', (s.challenge?.paragraphs?.[0]||'').slice(0,100));
  console.log('  steps:', (s.solution?.steps||[]).map(x=>x.title).join(' / '));
});
"

